    "starterJS": "const passwordInput = document.getElementById(\"password-input\");\n// TODO: Select toggleBtn\n\n// TODO [JavaScript]:\n// 1. Listen for click on toggleBtn\n// 2. Toggle passwordInput type between \"password\" and \"text\"\n// 3. Alternate button text between \"Hide Password\" and \"Show Password\"\n",
    "solutionHTML": "<div class=\"card\">\n  <h2>Account Security</h2>\n  <div class=\"input-container\">\n    <input type=\"password\" id=\"password-input\" value=\"SuperSecret123!\" placeholder=\"Enter password\" />\n    <button id=\"toggle-btn\" class=\"toggle-btn\">Show Password</button>\n  </div>\n</div>",
    "solutionCSS": "* {\n  box-sizing: border-box;\n  font-family: 'Segoe UI', system-ui, sans-serif;\n}\nbody {\n  margin: 0;\n  padding: 24px;\n  background: #f8fafc;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  min-height: 100vh;\n}\n.card {\n  background: #ffffff;\n  padding: 32px;\n  border-radius: 12px;\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);\n  width: 100%;\n  max-width: 380px;\n}\nh2 {\n  margin-top: 0;\n  color: #0f172a;\n  font-size: 20px;\n  margin-bottom: 20px;\n}\n.input-container {\n  display: flex;\n  gap: 8px;\n}\n#password-input {\n  flex: 1;\n  padding: 10px 14px;\n  border: 1px solid #cbd5e1;\n  border-radius: 6px;\n  font-size: 14px;\n  outline: none;\n}\n/* TODO [CSS]: Style #toggle-btn with cursor: pointer and border-radius: 6px */\n#toggle-btn {\n  background: #f1f5f9;\n  border: 1px solid #cbd5e1;\n  color: #334155;\n  padding: 10px 14px;\n  border-radius: 6px;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n}",
    "solutionJS": "const passwordInput = document.getElementById(\"password-input\");\nconst toggleBtn = document.getElementById(\"toggle-btn\");\n\nif (toggleBtn) {\n  toggleBtn.addEventListener(\"click\", () => {\n    if (passwordInput.type === \"password\") {\n      passwordInput.type = \"text\";\n      toggleBtn.textContent = \"Hide Password\";\n    } else {\n      passwordInput.type = \"password\";\n      toggleBtn.textContent = \"Show Password\";\n    }\n  });\n}",
